arguments.command:
python3 -I - << 'EOF'
with open("observed_run/stdout.log") as f:
    lines = f.readlines()
print("Total lines in stdout.log:", len(lines))
for i, line in enumerate(lines[:100]):
    print(f"{i+1}: {line}", end="")
print("="*60)
for i, line in enumerate(lines):
    if any(k in line for k in ["val-core", "val-aux", "validation", "Validation", "step:100", "step:150", "####", "Error", "Exception", "WARNING"]):
        if len(line) < 500:
            print(f"{i+1}: {line}", end="")
        else:
            print(f"{i+1}: {line[:500]}...")
EOF

